def validate_generated_code():
    _get_ptx_module().function("sdp_attn_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        assert Q.is_cuda and K.is_cuda and V.is_cuda
        assert Q.dtype == torch.float16 and K.dtype == torch.float16 and V.dtype == torch.float16
        B, H, S, D = Q.shape
        assert S <= 256, "Kernel requires S <= 256 due to shared-memory slogits buffer"
        assert D <= 4 * 256, "Kernel requires D <= 1024 for the 4*blockDim.x lane mapping"
        out = torch.empty_like(Q)
        module = _get_ptx_module()
        module.launch(
            "sdp_attn_kernel",
            grid=(S, H, B),
            block=(256, 1, 1),
            arguments=[Q, K, V, out, i32(B), i32(H), i32(S), i32(D)],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

